/// <summary>
/// This class is called METPickDirectorDataEntitity has done the import.
/// </summary>
class METPickDirectorDataController_New
{
}

Method.Source:
/// <summary>
/// Process the sales orders which are macthing with the METPickDirectorData.
/// </summary>
public void processSOForPickDirectorData()
{
    #OCCRetryCount
    System.Exception netExcepn;

    SalesLine salesLine;
    METPickDirectorData pickDirectorData;
    Query qry = new Query(QueryStr(SalesUpdate));
    QueryBuildDataSource queryBuildDataSource = qry.dataSourceTable(tableNum(SalesLine));
    QueryBuildRange queryBuildRange;

    try
    {
        ttsbegin;
        while select QtyPicked from pickDirectorData
            join salesLine
            where salesLine.SalesId == pickDirectorData.SalesId
            && salesLine.LineNum == pickDirectorData.LineNum
            && salesLine.ItemId == pickDirectorData.ItemId
            && salesLine.SalesStatus == SalesStatus::Backorder
        {
            InventQty qtyPicked = pickDirectorData.QtyPicked;
            queryBuildRange = queryBuildDataSource.addRange(fieldnum(SalesLine, RecId));
            queryBuildRange.value(SysQuery::value(salesLine.RecId));

            // Reservation
            if (qtyPicked > 0)
            {
                this.reserveSOLineQty(salesLine, qtyPicked);
            }

        }
        ttscommit;

        ttsbegin;
        // Generate and post picking list
        List pickingRouteIDList = this.createSalesPickingListSingleLine(qry);

        // Register picking list
        if (!pickingRouteIDList.empty())
        {
            this.registerPickingList(pickingRouteIDList);
        }
        ttscommit;
    }
    catch (Exception::CLRError)
    {
        netExcepn = CLRInterop::getLastException();
        throw error(netExcepn.ToString());
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        else
        {
            throw Exception::UpdateConflict;
        }
    }
    catch
    {
        exceptionTextFallThrough();
    }
    finally
    {
        delete_from pickDirectorData;
    }
}

/// <summary>
/// Reserves the sales order line with the quantity picked.
/// </summary>
public void reserveSOLineQty(SalesLine _salesLine, InventQty _qtyPicked)
{
    InventMovement movement = InventMovement::construct(_salesLine);
    InventUpd_Reservation reservation = InventUpd_Reservation::newMovement(movement, -_qtyPicked, true);
    reservation.updateNow();
}

/// <summary>
/// Generated and posts the picking list for the sales order line with the quantity picked.
/// </summary>
/// <param name = "_qry">_qry</param>
/// <returns>WMSPickingRouteID</returns>
public List createSalesPickingListSingleLine(Query _qry)
{
    SalesFormLetter salesFormLetter = SalesFormLetter::construct(DocumentStatus::PickingList);

    salesFormLetter.chooseLinesQuery(this.calcQuery(_qry));
    salesFormLetter.transDate(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()));
    salesFormLetter.specQty(SalesUpdate::All);
    salesFormLetter.proforma(NoYes::No);
    salesFormLetter.printout(Printout::Current);
    salesFormLetter.printFormLetter(NoYes::No);
    salesFormLetter.usePrintManagement(NoYes::No);
    salesFormLetter.chooseLines(false, true);
    salesFormLetter.sumBy(AccountOrder::Order);
    salesFormLetter.reArrangeNow(false);

    SalesParmLine salesParmLine;

    while select forupdate salesParmLine
        where salesParmLine.ParmId == salesFormLetter.parmId()
    {
        SalesLine salesline = salesParmLine.salesLine();
        salesParmLine.DeliverNow = METPickDirectorData::find(salesline.SalesId, salesline.LineNum).QtyPicked;
        salesParmLine.setQty(DocumentStatus::PickingList, false);
        salesParmLine.update();
    }

    salesFormLetter.run();

    List list = new List(Types::String);
    WMSPickingRoute wmsPickingRoute;

    while select pickingRouteID from wmsPickingRoute
        where wmsPickingRoute.parmid == salesFormLetter.parmId()
    {
        list.addEnd(wmsPickingRoute.pickingRouteID);
    }

    return list;
}

/// <summary>
/// Registers the picking list for the selected sales line.
/// </summary>
/// <param name = "_pickingRouteID">_pickingRouteID</param>
public void registerPickingList(List _list)
{
    WMSPickingRoute::finishMulti(_list.pack());
}

/// <summary>
/// Calculate query for list of sales lines.
/// </summary>
/// <param name = "_qry">_qry</param>
/// <returns>SysQueryRun</returns>
private SysQueryRun calcQuery(Query _qry)
{
    return new sysQueryRun(_qry);
}
